      {
        "title": "원문·그림 확인 결과",
        "body": "1번 본문은 300 m와 −0.85 V를 제시하고, 별도로 LPG시설·황산염환원박테리아 토양의 −0.95 V를 인용합니다. 해당 전위측정 사진이나 토양 조건 이미지는 없습니다.\n남은 확인사항: 고압가스시설과 LPG시설 인용범위 차이, 토양 조건이 남습니다."
      }
