  "223428696524-6": {
    "text": "LNG는 혼합물이며 이 문제는 주성분 메탄의 성질을 묻습니다. 핵심은 CH₄, 공기 중 가연범위 약 5~15 vol%, 대기압 비점 약 −161.5℃입니다.\n증기비중 계산: 같은 온도·압력에서 이상기체 밀도는 분자량에 비례하므로 S=ρCH₄/ρair=MCH₄/Mair=(12+4×1)/29=16/29=0.5517≈0.55. 두 분자량 단위 g/mol이 약분되어 비중은 단위가 없습니다. 액체 비중을 계산한 것이 아닙니다.\n따뜻해진 메탄 기체는 공기보다 가볍지만 극저온 누출 초기에는 찬 증기와 공기가 섞여 낮은 곳에 머물 수 있습니다. 액화가스 접촉은 동상과 재료 취화를 일으킬 수 있으므로 꽃이 부서지는 장면을 단순 독성으로 설명하지 마세요.",
    "sources": [
      {
        "title": "2024년 1회 작업형 복원 원문",
        "url": "https://blog.naver.com/shipbuilding_pro/223428696524"
      },
      {
        "title": "ILO/WHO 국제화학물질안전카드 0291 메탄",
        "url": "https://www.inchem.org/documents/icsc/icsc/eics0291.htm"
      }
    ],
    "kind": "calculation"
  },
