        "body": "도판은 터미널이 오목한 곳에 놓일 때 둘러싼 좌우·상하 돌출물 사이의 열린 폭을 1.5 m 이상으로 표시합니다. “터미널에서 모든 벽까지 1.5 m”로 읽으면 그림과 다릅니다."
