  "223428696524-8": {
    "text": "(가) 물분무장치, (나) 매월 1회 이상 작동 점검이 복원답입니다. 탱크 간 거리는 한 탱크 사고의 열이 인접 탱크로 전해지는 것을 줄이고, 물분무는 노출되는 표면을 냉각하여 열 영향을 완화합니다.\n정해진 간격을 확보하지 못할 때 아무 살수설비나 설치하면 된다는 의미는 아닙니다. 설계 분무범위·수량·공급 신뢰성이 필요하며 이 문항에는 그 수치가 없습니다. 점검은 외관을 보는 것과 실제 작동 확인이 다르다는 점을 기억하세요.\n\n수치·주기·시설 예외는 해당 연도 블로그 복원답 기준입니다. 현재 설계·시공 기준으로 인증한 내용은 아니므로 응시 시점의 KGS 기준과 구분해 공부하세요.",
    "sources": [
      {
        "title": "2024년 1회 작업형 복원 원문",
        "url": "https://blog.naver.com/shipbuilding_pro/223428696524"
      }
    ],
    "kind": "concept"
  },
  "223428696524-9": {
    "text": "F는 퓨즈콕, 1.2는 복원 기준에서 과류차단 안전기구의 표시유량 1.2 m³/h를 뜻합니다. 압력 1.2 MPa라는 뜻이 아닙니다.\n호스 이탈 등으로 가스가 정상보다 많이 흐르면 내부 과류차단기구가 유로를 차단합니다. 열로 녹는 전기 퓨즈와 이름이 비슷하지만 감지 대상은 유량입니다. 표시유량에 못 미치는 작은 누설까지 모두 검출하는 누설경보기는 아닙니다. 환산하면 1.2 m³/h=1,200 L/h=20 L/min으로, 부피/시간이라는 단위의 뜻을 확인할 수 있습니다.\n\n수치·주기·시설 예외는 해당 연도 블로그 복원답 기준입니다. 현재 설계·시공 기준으로 인증한 내용은 아니므로 응시 시점의 KGS 기준과 구분해 공부하세요.",
    "sources": [
      {
        "title": "2024년 1회 작업형 복원 원문",
        "url": "https://blog.naver.com/shipbuilding_pro/223428696524"
      }
    ],
    "kind": "calculation"
  },
  "223428696524-10": {
    "text": "원문은 Ex d 장치에 최소점화전류비를 물었다며 문제 오류로 해석하지만, 가스그룹 IIB와 그 분류 물성 자체를 질문할 수도 있으므로 “답을 쓸 수 없다”는 해석을 확정하지 않습니다. 복원자료가 제시한 IIB 최소점화전류비는 0.45~0.8, 최대안전틈새는 0.5 mm 초과 0.9 mm 미만입니다. 적용 표준 판·경계값을 별도 확인해야 합니다.\nEx d는 내부 폭발이 외부 폭발성 분위기에 전파되지 않도록 하는 내압방폭을 뜻합니다. T4의 기기 최고표면온도는 135℃ 이하이며, 원문이 묻는 옛 “가스 발화도 범위” 135℃ 초과 200℃ 이하와 서로 다른 항목입니다. 기기 표면온도를 200℃까지 허용한다고 쓰지 마세요.\n\n수치·주기·시설 예외는 해당 연도 블로그 복원답 기준입니다. 현재 설계·시공 기준으로 인증한 내용은 아니므로 응시 시점의 KGS 기준과 구분해 공부하세요.",
    "sources": [
      {
        "title": "2024년 1회 작업형 복원 원문",
        "url": "https://blog.naver.com/shipbuilding_pro/223428696524"
      },
      {
        "title": "IECEx 방폭 방식과 온도등급 교육자료",
        "url": "https://www.iecex.com/assets/Uploads/D2S2-Ex-Protection-Techniques-BARTEC.pdf"
      }
    ],
    "kind": "concept"
  },
  "223295128732-1": {
    "text": "용기는 사이펀 용기이며 원칙적으로 기화장치가 있는 시설에서 사용한다는 복원답입니다. 바닥까지 내려간 사이펀관으로 액상 LPG를 꺼내 외부 기화기로 보내고, 기화기는 열을 공급해 액체를 기체로 바꿉니다. 일반 가정용 용기는 보통 용기 안에서 자연 기화한 증기를 사용합니다.\n차이는 용기 용량이 아니라 액체 인출 경로와 기화 위치입니다. 액체가 바로 기체용 연소기 배관에 들어가면 급격한 팽창·비정상 공급 위험이 생깁니다. 원문에 자연기화 밸브 대체 운전 설명이 있지만, 실제 기화기 고장 때 임의로 우회 운전해도 된다는 지침으로 해석하지 마세요.\n\n수치·주기·시설 예외는 해당 연도 블로그 복원답 기준입니다. 현재 설계·시공 기준으로 인증한 내용은 아니므로 응시 시점의 KGS 기준과 구분해 공부하세요.",
    "sources": [
      {
        "title": "2023년 3회 작업형 복원 원문",
        "url": "https://blog.naver.com/shipbuilding_pro/223295128732"
      }
    ],
    "kind": "concept"
  },
